class Solution:
    def isStrobogrammatic(self, num: str) -> bool:
        rotation = {'0': '0', '1': '1', '6': '9', '8': '8', '9': '6'}
        if any(digit not in rotation for digit in num):
            return False
        return ''.join(rotation[digit] for digit in reversed(num)) == num
